import{_ as a,H as s,f as t,i as o}from"./chunks/framework.CBmkDW73.js";const h=JSON.parse('{"title":"subagents","description":"","frontmatter":{},"headers":[],"relativePath":"ko/skills/subagents.md","filePath":"ko/skills/subagents.md"}'),d={name:"ko/skills/subagents.md"};function l(n,e,c,i,r,p){return s(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="subagents" tabindex="-1">subagents <a class="header-anchor" href="#subagents" aria-label="Permalink to &quot;subagents&quot;">​</a></h1><p><code>subagents</code> 스킬은 계획의 <code>[parallel]</code> 마일스톤 작업을 독립된 컨텍스트 창, 명시적 역할 계약(ROLE) 및 선택적 기능 티어 모델 라우팅(MODEL)을 갖춘 서브에이전트에 배포합니다.</p><h2 id="배포-및-쓰기-격리" tabindex="-1">배포 및 쓰기 격리 <a class="header-anchor" href="#배포-및-쓰기-격리" aria-label="Permalink to &quot;배포 및 쓰기 격리&quot;">​</a></h2><p>마일스톤의 원자적 단계 전개는 배포 시점에만 수행하며, 본문을 붙여넣지 않고 명세/계획 파일 경로를 전달합니다:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TASK: &lt;한 문장 작업&gt;</span></span>
<span class="line"><span>ROLE: &lt;implementer | spec-reviewer | quality-reviewer&gt;</span></span>
<span class="line"><span>MODEL: &lt;fast | balanced | strongest&gt;</span></span>
<span class="line"><span>REPOSITORY / MODULE / FILES / SPEC / ACCEPTANCE / EXTRA</span></span></code></pre></div><p>한 작업은 하나의 리포지토리/모듈 쓰기 범위만 가지며, 겹치는 모듈 루트에 동시에 여러 쓰기 에이전트를 배포하지 않습니다. 필요한 모듈의 로컬 수용 검증이 모두 통과한 뒤에만 통합 작업을 배포하며, <code>- [x]</code> 표시는 Coordinator만 수행합니다.</p><h2 id="역할-루프-및-상태-처리" tabindex="-1">역할 루프 및 상태 처리 <a class="header-anchor" href="#역할-루프-및-상태-처리" aria-label="Permalink to &quot;역할 루프 및 상태 처리&quot;">​</a></h2><p>작업당 실행 루프: <code>implementer</code>(기본 <code>balanced</code>) → <code>spec-reviewer</code>(기본 <code>fast</code>) → <code>quality-reviewer</code>(기본 <code>strongest</code>) → Coordinator 완료 표시. 반환 상태를 명시적으로 처리합니다:</p><ul><li><code>DONE_WITH_CONCERNS</code>: 정확성 문제면 해결하고, 단순 관찰 사항이면 기록합니다.</li><li><code>NEEDS_CONTEXT</code>: 누락된 사실을 보완해 재배포합니다.</li><li><code>BLOCKED</code>: 무작정 재시도하지 말고 차단 원인(컨텍스트 부족 / 모델 능력 부족 / 과도한 작업 크기 / 계획 오류)을 진단합니다.</li></ul><h2 id="모델-티어" tabindex="-1">모델 티어 <a class="header-anchor" href="#모델-티어" aria-label="Permalink to &quot;모델 티어&quot;">​</a></h2><p><code>MODEL</code>(<code>fast | balanced | strongest</code>)을 생략하면 하네스 기본 모델을 사용합니다. <code>.praxis/model-tiers.yaml</code>로 매핑 가능하며(해결 순서: 프로젝트 <code>.praxis/model-tiers.yaml</code> → 사용자 <code>~/.praxis/model-tiers.yaml</code> → 하네스 기본 모델), 저장소 루트 <code>model-tiers.example.yaml</code>의 <code>tiers.&lt;tier&gt;.{provider, model}</code> 스키마를 따릅니다.</p>`,11)])])}const m=a(d,[["render",l]]);export{h as __pageData,m as default};
